.ds-pill-switch {
  display: inline-flex;
  align-items: center;
  gap: 0;
  min-height: 44px;
  position: relative;
  padding: 0;
  cursor: pointer;
  background: none;
  border: none;
  font: inherit;
  color: inherit;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.ds-pill-switch__track {
  position: absolute;
  inset: 0;
  border-radius: var(--radius-xl);
  background: rgba(255, 255, 255, 0.06);
  border: none;
  transition: background-color var(--transition-smooth);
  z-index: 0;
}

.ds-pill-switch__thumb {
  position: absolute;
  top: 3px;
  left: 3px;
  width: calc(50% - 6px);
  height: calc(100% - 6px);
  border-radius: var(--radius-xl);
  background: rgba(255, 255, 255, 0.08);
  border: none;
  transform: translateX(0);
  transition:
    transform var(--transition-bounce),
    background-color var(--transition-smooth);
  z-index: 2;
}

.ds-pill-switch__label {
  position: relative;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  flex: 1;
  padding: var(--space-2) var(--space-4);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  pointer-events: none;
}

.ds-pill-switch__label--left,
.ds-pill-switch__label--right {
  color: var(--color-text-secondary);
}

.ds-pill-switch__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.ds-pill-switch__text {
  white-space: nowrap;
}

.ds-pill-switch[aria-checked="true"] .ds-pill-switch__track {
  background: var(--color-accent);
}

.ds-pill-switch[aria-checked="true"] .ds-pill-switch__thumb {
  background: var(--color-accent);
